import json
import re
from html import unescape
from pathlib import Path

SOURCES = json.loads(Path('source.json').read_text())
REFS = json.loads(Path('reference-targets.json').read_text())
BY_NUMBER = {a['number']: a for a in SOURCES}
ANSWERS = {}


def plain(xml):
    return unescape(re.sub(r'<[^>]*>', '', xml))


def paragraphs(*items):
    return '\n'.join('<p>' + t + '</p>' for t in items)


def source_paragraph(number, start):
    xml = BY_NUMBER[number]['source_xml']
    for p in re.findall(r'<p(?:\s[^>]*)?>(.*?)</p>', xml, re.S):
        if start in plain(p):
            return plain(p)
    text = plain(xml)
    assert start in text, (number, start)
    return start


def effect(number, kind, measure_id, description, before, after, unit,
           population, transition, source_quote, proposed_quote):
    return dict(kind=kind, measure_id=measure_id, description=description,
                before=before, after=after, unit=unit,
                affected_population=population,
                conditions_and_transition=transition,
                replacement_or_new_burdens='Aucune taxe, déclaration, autorisation, attestation ou registre de remplacement n’est institué par cette mesure. Les obligations autonomes expressément réservées conservent leur champ.',
                source_quote=source_quote, proposed_quote=proposed_quote)


def impact(classification, assessment, scope, burdens, effects):
    return dict(version=1, classification=classification, assessment=assessment,
                scope_limitations=scope, new_burdens_review=burdens, effects=effects)


def base(number, xml, reason, notes, substantive, checks=None, benefit=None,
         repeal_scope=None, removed=None):
    s = BY_NUMBER[number]
    a = {k: s[k] for k in ['code_id', 'source_id', 'source_sha256', 'number']}
    a.update(proposed_xml=xml, reason=reason, review_notes=notes,
             status='retained_unchanged' if xml is None else 'rewrite_draft',
             substantive_impact=substantive)
    if xml is None:
        a['classification'] = 'retained_necessary'
    if repeal_scope:
        a.update(change_type='full_repeal', repeal_policy_id='editorial_direction_2026_10_19', repeal_scope=repeal_scope)
    if removed:
        a.update(change_type='normative_reduction', reform_policy_id='editorial_direction_2026_10_19', removed_provisions=removed)
    a['reference_checks'] = []
    for key, assessment in (checks or {}).items():
        a['reference_checks'].append(dict(target_key=key,
                                         view_sha256=REFS['targets'][key]['view_sha256'],
                                         assessment=assessment))
    if benefit is not None:
        a['benefit_review'] = benefit
    ANSWERS[number] = a


